{"code": "def build_maze(frame):
    a = frame.ascii.split('\n')
    rows=list(range(4,60,5)); cols=list(range(4,60,5))
    open_cells=set()
    for r in rows:
        for c in cols:
            if all(a[r+i][c+j] in 'BS' for i in range(5) for j in range(5)):
                open_cells.add((r,c))
    return open_cells

def blocks(frame):
    out=[]
    for n in frame.segmentation['nodes']:
        if n['color']=='S':
            out.append(tuple(n['boundary'][0]))
    return sorted(out)

oc = build_maze(current_frame)
print(len(oc))
bl = blocks(current_frame)
print('blocks', bl)
# adjacency
def nb(cell):
    r,c=cell
    return [d for d in ((r-5,c),(r+5,c),(r,c-5),(r,c+5)) if d in oc]
# degrees / deadends
deg = {c:len(nb(c)) for c in oc}
print('deadends', sorted([c for c,d in deg.items() if d<=1]))
print('row9 cells', sorted(c for c in oc if c[0]==9))
