def step(st, d):
    dr,dc = DIRS[d]
    tgt = [ (p[0]+dr,p[1]+dc) for p in st ]
    ok = [ (t in oc) for t in tgt ]
    # collision: target occupied by other block -> blocked
    for i in range(2):
        if ok[i] and tgt[1-i] == tgt[i]: ok[i]=False
        if ok[i] and tgt[i]==st[1-i]: ok[i]=False
    return tuple(tgt[i] if ok[i] else st[i] for i in range(2))
